// Bottom navigation icons exported from Figma (28 x 28, ic28 set).
import 'package:flutter/material.dart';
import 'package:path_parsing/path_parsing.dart';

/// A Figma ic28 navigation icon drawn from its vector path.
class NavIcon extends StatelessWidget {
  const NavIcon(this.path, {super.key, required this.color, this.evenOdd = false, this.size = 28});
  final String path;
  final Color color;
  final bool evenOdd;
  final double size;
  @override
  Widget build(BuildContext context) => CustomPaint(size: Size.square(size), painter: _P(path, color, evenOdd));
}

class _P extends CustomPainter {
  _P(this.d, this.color, this.evenOdd);
  final String d;
  final Color color;
  final bool evenOdd;
  static final _cache = <String, Path>{};
  @override
  void paint(Canvas canvas, Size size) {
    final p = _cache.putIfAbsent(d, () {
      final path = Path();
      writeSvgPathDataToPath(d, _Proxy(path));
      return path;
    });
    canvas.scale(size.width / 28);
    canvas.drawPath(p..fillType = evenOdd ? PathFillType.evenOdd : PathFillType.nonZero, Paint()..color = color);
  }
  @override
  bool shouldRepaint(_P o) => o.d != d || o.color != color;
}

class _Proxy extends PathProxy {
  _Proxy(this.p);
  final Path p;
  @override
  void close() => p.close();
  @override
  void cubicTo(double x1, double y1, double x2, double y2, double x3, double y3) => p.cubicTo(x1, y1, x2, y2, x3, y3);
  @override
  void lineTo(double x, double y) => p.lineTo(x, y);
  @override
  void moveTo(double x, double y) => p.moveTo(x, y);
}

